<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Edit employee | <?= e(config('app.name')) ?></title><link rel="stylesheet" href="<?= e(app_url('/assets/css/app.css?v=20260710-daily-attendance')) ?>">    <link rel="icon" href="<?= e(app_url('/favicon.svg?v=clock-1')) ?>" type="image/svg+xml">
</head>
<body><?php require BASE_PATH . '/app/Views/partials/nav.php'; ?><main class="container narrow">
<div class="page-heading"><div><p class="eyebrow">People</p><h1>Edit <?= e($employee['first_name'].' '.$employee['last_name']) ?></h1></div><a class="back-link" href="<?= e(app_url('/employees')) ?>">← Back to employees</a></div>
<section class="panel"><form method="post" action="<?= e(app_url('/employees/' . $employee['id'] . '/edit')) ?>"><?= csrf_field() ?>
<label for="employee_number">Employee number</label><input id="employee_number" name="employee_number" value="<?= e($employee['employee_number']) ?>" required>
<div class="form-row"><div><label for="first_name">First name</label><input id="first_name" name="first_name" value="<?= e($employee['first_name']) ?>" required></div><div><label for="last_name">Last name</label><input id="last_name" name="last_name" value="<?= e($employee['last_name']) ?>" required></div></div>
<label for="phone">Phone</label><input id="phone" name="phone" value="<?= e($employee['phone']) ?>">
<label for="department_id">Department</label><select id="department_id" name="department_id" required><?php foreach($departments as $department):?><option value="<?= e($department['id']) ?>" <?= (int)$employee['department_id']===(int)$department['id']?'selected':'' ?>><?= e($department['name']) ?></option><?php endforeach;?></select>
<div class="form-row"><div><label for="hire_date">Hire date</label><input id="hire_date" name="hire_date" type="date" value="<?= e($employee['hire_date']) ?>"></div><div><label for="employment_type">Type</label><select id="employment_type" name="employment_type"><?php foreach(['full_time'=>'Full time','part_time'=>'Part time','contractor'=>'Contractor'] as $value=>$label):?><option value="<?= e($value) ?>" <?= $employee['employment_type']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></div></div>
<hr><h2>Attendance calculation</h2>
<input type="hidden" name="attendance_mode" value="flexible"><div class="alert success">Flexible automatic activity tracking · no shift required</div>
<div class="form-row"><div><label for="activity_attendance_effective_from">Activity mode starts</label><input id="activity_attendance_effective_from" name="activity_attendance_effective_from" type="date" value="<?= e($employee['activity_attendance_effective_from'] ?? date('Y-m-d')) ?>"></div><div><label for="daily_target_minutes">Daily target minutes</label><input id="daily_target_minutes" name="daily_target_minutes" type="number" min="1" max="1440" value="<?= e($employee['daily_target_minutes'] ?? 480) ?>"></div></div>
<div class="form-row"><div><label for="idle_threshold_minutes">Idle threshold minutes</label><input id="idle_threshold_minutes" name="idle_threshold_minutes" type="number" min="1" max="240" value="<?= e($employee['idle_threshold_minutes'] ?? 30) ?>"><small>The full idle period is excluded once reached.</small></div><div><label for="offline_timeout_minutes">Offline timeout minutes</label><input id="offline_timeout_minutes" name="offline_timeout_minutes" type="number" min="1" max="240" value="<?= e($employee['offline_timeout_minutes'] ?? 15) ?>"><small>Stops counting at the last confirmed activity.</small></div></div>
<button type="submit">Save changes</button></form></section></main></body></html>
